    'web.feedback.finish' => 'Terminer et voir le rapport',
    'web.done.title' => 'Voilà ce que votre heure a produit',
    'web.done.lead' => '%d sujet(s) déclaré(s), en %s.',
    'web.done.verdicts' => 'Le rapport, après vos réponses',
    'web.done.report' => 'Ouvrir le rapport',
    'web.done.files' => 'Écrit dans %s, compte rendu de séance dans %s.',
    // --- how long the system itself lives, and whose deadline applies ---
    'crossing.row.outlives' => '%s — %d ans — le système s\'arrête avant la bascule de %d : rien de ce qu\'il écrira ne franchira la ligne',
    'blind.service_until' => "L'horizon d'exploitation du système n'est pas déclaré : le calcul suppose qu'il cesse d'écrire des données aujourd'hui. C'est l'hypothèse optimiste — un service encore en production dans dix ans produira dix ans de données de plus à protéger. Ajoutez `service_until` à la déclaration.",
    'blind.service_until.declared' => 'Horizon d\'exploitation déclaré : le système cesse d\'écrire des données en %d. La dernière donnée émise est exposée à partir de cette année-là, pas d\'aujourd\'hui.',
    'blind.regime' => 'Échéance retenue : %d, d\'après %s. Un autre cadre — institutionnel, défense — donne une autre date : voir `regime` dans la déclaration.',
    'blind.regime.graded' => "Échéances retenues : %d pour le haut risque et %d pour le risque moyen, d'après %s. Le niveau de chaque domaine est lu sur la durée de confidentialité que vous avez déclarée, donc une durée corrigée déplace l'échéance de ce domaine.",
    'declare.q.service' => "Jusqu'à quelle année ce service tournera-t-il ? (vide si vous ne savez pas)",
    'declare.q.regime' => "Dans quel cadre ? 1 = commercial ou grand public · 2 = institutionnel, données sensibles (ANSSI) · 3 = systèmes de sécurité nationale (CNSA 2.0)",
    'declare.regime.set' => '→ Échéance retenue : %d, d\'après %s.',
    'declare.service.set' => '→ Les données écrites jusqu\'en %d sont prises en compte.',
    'declare.service.unknown' => '→ Non déclaré : le calcul supposera que le système s\'arrête aujourd\'hui, et le rapport dira que c\'est optimiste.',
    // --- the interview: the only input no scanner can read ---
    'declare.intro' => "Je vais vous montrer, sujet par sujet, ce que l'application protège — et vous poser trois questions courtes sur chacun.\n  Aucune n'est technique. Si vous ne savez pas, on passe : ce qui reste sans réponse sera écrit comme tel dans le rapport, plutôt qu'inventé.\n  Rien n'est enregistré avant la fin. Ce qui le sera : vos réponses, qui deviennent les durées du rapport d'audit avec vos mots comme justification, et un compte rendu de séance qui ne sert qu'à corriger l'outil.",
    'declare.found' => '%d sujet(s) à parcourir — comptez une à deux minutes chacun.',
    'declare.target' => 'Projet : %s',
    'declare.area' => 'Sujet %d sur %d · %d fichier(s)',
    'declare.area.where' => 'Dans : %s',
    'web.details' => 'Détails techniques',
    'declare.subject.plaintext' => "Ici, l'application garde des réglages qu'elle lit au démarrage : à qui elle se connecte, avec quel compte, et avec quel mot de passe. Ce n'est pas chiffré — c'est un fichier de configuration.",
    'declare.subject.vault' => "Ici, l'application range des secrets dans un coffre : mots de passe, clés, jetons d'accès aux services qu'elle utilise. Le coffre est chiffré, et il protège tout le reste.",
    'declare.subject.asymmetric' => "Ici, l'application chiffre quelque chose avec une clé publique — typiquement pour que seul le destinataire puisse le relire, ou pour protéger une sauvegarde.",
    'declare.subject.encrypted' => "Ici, l'application chiffre du contenu avant de le ranger ou de l'envoyer. Le chiffrement sert à ce que personne d'autre ne puisse le lire.",
    'declare.subject.signature' => "Ici, l'application signe quelque chose : elle prouve que c'est bien elle qui l'a émis, ou elle vérifie la signature de quelqu'un d'autre. Une signature ne cache rien, elle authentifie.",
    'declare.subject.passwords' => "Ici, l'application range des mots de passe sous une forme qui ne permet pas de les relire, seulement de les vérifier.",
    'declare.subject.digest' => "Ici, l'application calcule une empreinte sur un contenu : une sorte de résumé qui change dès que le contenu change. Sert à vérifier qu'une chose n'a pas été modifiée, ou à fabriquer un jeton.",
    'declare.subject.other' => "Ici, l'application fait quelque chose de cryptographique que cet entretien n'a pas besoin de détailler.",
    'declare.q.name' => 'Si quelqu\'un en obtenait une copie, de quoi parlerait-on, dans vos mots ?',
    'declare.subject.plaintext.label' => 'Réglages de connexion',
    'declare.subject.vault.label' => 'Un coffre à secrets',
    'declare.subject.asymmetric.label' => 'Chiffrement à clé publique',
    'declare.subject.encrypted.label' => 'Contenu chiffré',
    'declare.subject.signature.label' => 'Signatures',
    'declare.subject.passwords.label' => 'Mots de passe',
    'declare.subject.digest.label' => 'Empreintes de contenu',
    'declare.subject.other.label' => 'Cryptographie',
    'declare.q.name.first' => 'Si quelqu\'un en obtenait une copie, de quoi parlerait-on, dans vos mots ? (exemples : comptabilité, dossiers clients, pièces jointes)',
    'declare.q.retention' => 'Combien d\'années devez-vous garder ça ? (obligation légale, contrat, ou votre propre règle ; 0 si rien ne l\'impose)',
    'declare.q.damage' => 'Si ça sortait aujourd\'hui, pendant combien d\'années est-ce que ça ferait encore du tort ? (0 si c\'est public ou sans conséquence)',
