    'declare.derived.why.damage' => 'Elle vient du tort causé : il dure plus longtemps que l\'obligation de conservation.',
    'declare.derived.why.zero' => 'Rien à protéger dans la durée : ni conservation imposée, ni tort durable.',
    'declare.skipped' => '→ Passé. Le rapport dira que ce sujet n\'a pas de durée, plutôt que d\'en inventer une.',
    'declare.invalid' => 'Un nombre d\'années, s\'il vous plaît (0 si aucune).',
    'declare.invalid.year' => 'Une année, s\'il vous plaît — par exemple 2032.',
    'declare.written' => '%d domaine(s) écrit(s) dans %s. Relisez-le, discutez-le, versionnez-le.',
    'declare.nothing' => "Aucune zone sans durée : la déclaration couvre déjà tout ce que l'analyse a trouvé.",
    'declare.area.time' => '→ %.1f s sur cette zone.',
    'declare.times' => 'Temps par sujet :',
    'declare.times.skipped' => 'passée',
    'declare.times.unknown' => 'ne sait pas',
    'declare.elapsed' => 'Entretien terminé en %s — %d question(s) répondue(s), %d passée(s).',
    // --- the date a domain crosses the line ---
    'crossing.title' => 'Dates de bascule',
    'crossing.intro' => "Une donnée chiffrée l'année Y reste sensible jusqu'à Y + sa durée. L'année de bascule est donc celle à partir de laquelle tout ce qui est chiffré survit à la péremption de %d : avant, le domaine tient ; à partir d'elle, ce qui est émis est déjà perdu le jour où l'algorithme tombe.",
    'crossing.intro.graded' => "Une donnée chiffrée l'année Y reste sensible jusqu'à Y + sa durée. L'année de bascule est donc celle à partir de laquelle tout ce qui est chiffré survit à la péremption de l'algorithme qui le protège — une date propre à chaque domaine sous ce régime : avant, le domaine tient ; à partir d'elle, ce qui est émis est déjà perdu le jour où l'algorithme tombe.",
    'crossing.row' => '%s — %d ans — bascule le 1er janvier %d',
    'crossing.row.past' => '%s — %d ans — bascule franchie depuis %d',
    'crossing.none' => "Aucun domaine ne bascule : soit les durées déclarées sont plus courtes que la fenêtre, soit rien d'exposé à la récolte n'y est protégé par un algorithme que le quantique casse.",
    'crossing.next' => 'Prochaine bascule : %s, le 1er janvier %d.',
    'crossing.next.past' => '%s a déjà basculé en %d : ce qui y est chiffré aujourd\'hui survit à la péremption.',
    'crossing.calendar.name' => 'Sablier — bascules de %s',
    'crossing.calendar.summary' => 'Bascule du domaine %s (%s)',
    'crossing.calendar.description' => "À partir de ce jour, une donnée du domaine %s chiffrée avec un algorithme vulnérable reste confidentielle %d ans, donc au-delà de la péremption de %d. Migrer après cette date ne protège plus ce qui a déjà été émis.",
    // --- binary assets: what hides where nobody reads ---
    'blind.assets' => "Les fichiers binaires (images, polices, archives) ne sont lus que sur leurs premiers méga-octets, et seulement pour trois signes vérifiables : un bloc de clé, des octets après la fin de l'image, une extension qui ment sur le contenu. Un message dissimulé dans les bits d'une image n'est pas détecté ici, et ne prétend pas l'être.",
    'detail.asset.key' => "Bloc de clé trouvé à l'octet %2\$d d'un fichier .%1\$s. Un asset binaire n'est pas un endroit où du matériel de clé arrive par accident.",
    'detail.asset.trailing' => "L'image se termine à l'octet %d et le fichier continue au-delà. C'est souvent anodin — profil colorimétrique, filigrane ajouté par un outil — et parfois non. À ouvrir pour confirmer, pas à corriger d'office.",
    'detail.asset.magic' => "Le contenu ne correspond pas à l'extension. Un fichier renommé est banal ; un fichier déguisé l'est moins. À confirmer.",
    // --- published vulnerabilities in declared libraries ---
    'advisories.no_docker' => "collecte impossible : Docker est requis pour exécuter le scanner de vulnérabilités sans rien installer sur cette machine.",
    'advisories.running' => 'collecte des vulnérabilités publiées avec %s…',
    'advisories.failed' => '%s n\'a rien produit : collecte abandonnée.',
    'advisories.written' => '%s — %d bibliothèque(s) cryptographique(s) concernée(s), %d autre(s) paquet(s) vulnérable(s) laissé(s) de côté.',
    'advisories.next' => 'Puis : sablier scan <chemin> --advisories=%s',
    'advisories.unreadable' => 'fichier de vulnérabilités illisible : %s',
    'advisories.blind.used' => 'Vulnérabilités publiées : base %s du %s, %d bibliothèque(s) cryptographique(s) concernée(s). %d autre(s) paquet(s) vulnérable(s) ne sont pas de la cryptographie et ne sont pas jugés ici.',
    'advisories.blind.absent' => "Les vulnérabilités publiées des dépendances n'ont pas été vérifiées : lancez `sablier advisories <chemin>` puis `--advisories=<fichier>`. Sans cela, une bibliothèque trouée aujourd'hui est présentée comme un simple inventaire.",

    // --- audit report: the second document, written to be read by people who
    // do not write code and may have to weigh it in a dispute ---
    'audit.doc_title' => "Rapport d'audit",
    'audit.doc_subtitle' => 'Exposition cryptographique et durées de confidentialité',
